import { ref, onMounted } from 'vue';
import axios from 'axios';
import { ElMessage } from 'element-plus';
export default {
  __name: 'SourceParamDialog',
  setup(__props, {
    expose: __expose
  }) {
    const dialogVisible = ref(false);
    const form = ref({
      containerName: '',
      memory: null,
      memorySwap: null,
      cpuQuota: null,
      cpuPeriod: 100000,
      // 默认值
      cpuShares: 1024 // 默认值
    });
    const containers = ref([]);

    // 获取容器列表
    const fetchContainers = async () => {
      try {
        const response = await axios.get('http://localhost:8081/container/list');
        containers.value = response.data || [];
      } catch (err) {
        ElMessage.error('获取容器列表失败');
      }
    };

    // 提交表单，更新容器资源
    const submit = async () => {
      if (!form.value.containerName) {
        ElMessage.warning('请选择容器');
        return;
      }
      try {
        await axios.post('http://localhost:8081/parameter/update', null, {
          params: {
            containerName: form.value.containerName,
            memory: form.value.memory,
            memorySwap: form.value.memorySwap,
            cpuQuota: form.value.cpuQuota,
            cpuPeriod: form.value.cpuPeriod,
            cpuShares: form.value.cpuShares
          }
        });
        ElMessage.success('资源配置成功');
        dialogVisible.value = false;
      } catch (err) {
        ElMessage.error('资源配置失败');
      }
    };

    // 初始化容器列表
    onMounted(() => {
      fetchContainers();
    });

    // 暴露给外部调用
    __expose({
      openDialog: () => {
        dialogVisible.value = true;
        fetchContainers(); // 每次打开时重新获取容器列表
      }
    });
    const __returned__ = {
      dialogVisible,
      form,
      containers,
      fetchContainers,
      submit,
      ref,
      onMounted,
      get axios() {
        return axios;
      },
      get ElMessage() {
        return ElMessage;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
